<script lang="ts">
	import type { Snippet } from 'svelte';
	import { Input } from '$lib/components/ui/input';
	import { Button } from '$lib/components/ui/button';
	import * as Select from '$lib/components/ui/select';

	type TypeOption = {
		value: string;
		label: string;
	};

	type Props = {
		placeholder?: string;
		value?: string;
		typeValue?: string;
		typeOptions?: TypeOption[];
		onSearch: () => void;
		disabled?: boolean;
		/**
		 * Optional slot for additional filters (extra selects, toggles). They render
		 * as standalone controls after the joined search unit and wrap onto their
		 * own row on narrow screens instead of squeezing the input.
		 */
		children?: Snippet;
	};

	let {
		placeholder = 'Search...',
		value = $bindable(''),
		typeValue = $bindable(''),
		typeOptions = [],
		onSearch,
		disabled = false,
		children
	}: Props = $props();

	const typeLabel = $derived(typeOptions.find((o) => o.value === typeValue)?.label ?? '');
</script>

<div class="flex flex-wrap items-center gap-2">
	<div class="flex min-w-fit flex-1 sm:min-w-0 sm:flex-initial">
		<Input
			{placeholder}
			class="h-9 w-full min-w-[140px] rounded-r-none border-r-0 shadow-none focus-visible:border-r focus-visible:border-ring focus-visible:ring-0 sm:w-[250px] lg:w-[320px]"
			bind:value
			onkeydown={(e) => {
				if (e.key === 'Enter') onSearch();
			}}
		/>

		{#if typeOptions.length > 0}
			<Select.Root type="single" bind:value={typeValue}>
				<Select.Trigger class="h-9 w-[110px] shrink-0 rounded-none border-r-0 shadow-none">
					{typeLabel}
				</Select.Trigger>
				<Select.Content>
					{#each typeOptions as option (option.value)}
						<Select.Item value={option.value} label={option.label}>
							{option.label}
						</Select.Item>
					{/each}
				</Select.Content>
			</Select.Root>
		{/if}

		<Button variant="outline" class="h-9 rounded-l-none shadow-none" onclick={onSearch} {disabled}>
			Go
		</Button>
	</div>

	{@render children?.()}
</div>
